mkdir -p /tmp/refund-test && cat > /tmp/refund-test/run.ts <<'EOF'
import { refundAgent } from 'src/agents.ts';
import { REFUNDS } from 'src/db.ts';

const show = (label: string, r: any) => {
  console.log(`--- ${label}`);
  console.log('finishReason:', r.finishReason);
  console.log('text:', r.text);
  console.log('interrupts:', JSON.stringify(r.interrupts.map((i: any) => ({ name: i.name, input: i.input }))));
  console.log('toolRequests:', JSON.stringify(r.toolRequests.map((t: any) => t.toolRequest?.name ?? t.name)));
};

const mode = process.argv[2];
const approved = mode === 'approve';
const chat = refundAgent.chat();

const r1 = await chat.send('I want a refund for order A-1001, it arrived broken.');
show('turn 1', r1);
const pending = r1.interrupts[0];
if (!pending) throw new Error('expected approveRefund interrupt');
const r2 = await chat.resume({ respond: [pending.respond({ approved, note: approved ? undefined : 'Not within policy' })] });
show(`turn 2 (approved=${approved})`, r2);
console.log('REFUNDS:', JSON.stringify(REFUNDS));
EOF
cd . && npx tsx /tmp/refund-test/run.ts approve 2>&1 | grep -v "UNDICI\|trace-warnings"

cat > /tmp/refund-test/edge.mts <<'EOF'
import { refundAgent } from 'src/agents.ts';
import { REFUNDS } from 'src/db.ts';

for (const msg of ['I want a refund for order A-1003, it was fine but I changed my mind.', 'I want a refund for order A-9999.', 'I want a refund, it arrived broken.']) {
  const r = await refundAgent.chat().send(msg);
  console.log('---', msg);
  console.log('finishReason:', r.finishReason, '| interrupts:', r.interrupts.length, '| text:', r.text);
}
console.log('REFUNDS:', JSON.stringify(REFUNDS));
EOF
cd . && npx tsx /tmp/refund-test/edge.mts 2>&1 | grep -v "UNDICI\|trace-warnings"
